head.script:

  scwin.onpageload = function() {
    scwin.createLinckedDataList('dltlnk_code', 'dataList2', 'dataList3', 'col1', 'upperCdId');
    grid01.setColumnNodeSet('col1', 'data:dataList1', 'cdNm', 'cdId');
    grid01.setColumnNodeSet('col2', 'data:dltlnk_code', 'cdNm', 'cdId');
    dataList3.insertRow();

    //btnUpload.bind('onclick', scwin.upload);
  };

  scwin.onpageunload = function() {

  };

  scwin.createLinckedDataList = function (
    linkedDataListId,
    oriDataListId,
    mstDataListId,
    mstColId,
    linkedRelatedColId
  ) {
    var lnkDataList = $p.getComponentById(linkedDataListId);
    if (!lnkDataList) {
      var conditionStr = "";
      if (mstDataListId && mstColId && linkedRelatedColId)
        conditionStr += linkedRelatedColId + ' == ref("data:' + mstDataListId + "." + mstColId + '")';

      lnkDataList = scwin.createLinckedDataListCond(linkedDataListId, oriDataListId, conditionStr);
    }
    return lnkDataList;
  };

  scwin.createLinckedDataListCond = function (linkedDataListId, oriDataListId, conditionStr) {
    var lnkDataList = $p.getComponentById(linkedDataListId);
    if (!lnkDataList) {
      if (!conditionStr) conditionStr = "";

      var info = {
        id: linkedDataListId,
        type: "linkedDataList",
        option: {
          valueAttribute: "",
          bind: oriDataListId,
          filterCondition: conditionStr,
          sortCondition: "",
        },
      };

      $p.data.create(info);
      lnkDataList = $p.getComponentById(linkedDataListId);
    }
    return lnkDataList;
  };

  scwin.upload = function(){
    var options = {
      "headerExist": 1,
      "skipSpace": 1,
      "type": 1,
      "processMsg": "파일 업로드 중 입니다."
    };

    gridUpload.advancedExcelUpload(options);
  };


	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('grid01_cell_0_1_select_input_0').value == '선택';
	}		
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
